  "properties": {
    "group_id": {
      "type": "string",
      "description": "Group ID to research (e.g., 'D_S01')"
    },
    "target_level": {
      "type": "integer",
      "description": "Target info level (2-5). If omitted, defaults to current_level + 1."
    }
  },
  "required": [
    "group_id"
  ]
}
