arguments.cmd:
/bin/bash -lc "./novamind-operation python-c \"
import novamind_api as nm, json
queries={
 'daily_market':'''SELECT start_day day,c.group_id,COUNT(*) leads,SUM(CASE WHEN s.status IN ('subscribed','cancelled') THEN 1 ELSE 0 END) joins,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active_new,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) churned_new,ROUND(AVG(CASE WHEN s.status IN ('subscribed','cancelled') THEN s.effective_price END),2) avg_eff FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE start_day>=210 GROUP BY start_day,c.group_id ORDER BY start_day,c.group_id''',
 'churn_day':'''SELECT s.end_day day,c.group_id,s.plan,COUNT(*) n,ROUND(AVG(s.effective_price),2) eff,ROUND(AVG(s.listed_price),2) listed FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.end_day>=210 AND s.status='cancelled' GROUP BY s.end_day,c.group_id,s.plan ORDER BY s.end_day,c.group_id,s.plan''',
 'all_active_by_day':'''SELECT d.day,c.group_id,SUM(CASE WHEN s.start_day<=d.day AND (s.end_day IS NULL OR s.end_day>d.day) AND s.status IN ('subscribed','cancelled') THEN 1 ELSE 0 END) active FROM (SELECT DISTINCT day FROM ledger WHERE day>=200) d CROSS JOIN customers c LEFT JOIN subscriptions s ON s.customer_id=c.customer_id GROUP BY d.day,c.group_id ORDER BY d.day,c.group_id''',
 'cohort_retention':'''SELECT s.start_day,c.group_id,COUNT(*) joins,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled,ROUND(100.0*SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END)/COUNT(*),1) churn_pct FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.start_day BETWEEN 150 AND 194 AND s.status IN ('subscribed','cancelled') GROUP BY s.start_day,c.group_id ORDER BY s.start_day,c.group_id''',
}
for name,sql in queries.items(): print('\\n###',name); print(json.dumps(nm.query(sql)['rows']))
\""

