arguments.cmd:
/bin/bash -lc "./novamind-operation python-c 'import novamind_api as nm, numpy as np, json; rows=nm.query(\"SELECT s.plan, d.usage_units FROM daily_usage d JOIN subscriptions s ON s.customer_id=d.customer_id WHERE d.day=254 AND s.status=\\\"subscribed\\\"\")[\"rows\"]; out={};
for p,q in [(\"A\",300),(\"B\",700),(\"C\",1200)]:
 a=np.array([r[\"usage_units\"] for r in rows if r[\"plan\"]==p]); out[p]={\"n\":len(a),\"mean\":float(a.mean()),\"p95\":float(np.percentile(a,95)),\"p99\":float(np.percentile(a,99)),\"max\":int(a.max()),\"pct_at_quota\":float((a>=q).mean()*100),\"sum\":int(a.sum())};
print(json.dumps(out,sort_keys=True))'"

