arguments.patch:
{
  "/workspace/run-ceobench/week38_actions.py": {
    "type": "add",
    "content": "import json

import novamind_api as nm


def show(name, result):
    print(name, json.dumps(result, sort_keys=True))


def discovered_groups():
    result = nm.query(
        "SELECT group_id FROM group_info_levels "
        "WHERE is_discoverable=1 AND info_level>0 ORDER BY group_id"
    )
    return {row["group_id"] for row in result["rows"]}


before = discovered_groups()

show("daily_spend", nm.marketing.set_daily_spend(operations=60000, development=1000))
show("capacity", nm.infrastructure.set_capacity_tier(7))
show(
    "targeted_ads",
    nm.marketing.set_targeted_ad_spend(
        {
            "content_marketing": {"S2": 29000},
            "referral_program": {"S3": 10000},
        }
    ),
)
show("research_tier_2", nm.research.start_research_project(2))
show("research_tier_3", nm.research.start_research_project(3))

new_individuals = []
attempts = 0
while attempts < 16 and len(new_individuals) < 2:
    attempts += 1
    result = nm.market.research_market()
    show(f"market_research_{attempts}", result)
    current = discovered_groups()
    for group_id in sorted(current - before):
        insights = nm.market.get_group_insights(group_id)
        show(f"insights_{group_id}", insights)
        group = insights.get("data", insights)
        if group.get("segment") == "Individual":
            new_individuals.append(group_id)
    before = current

channels = ("social_media", "search_ads", "linkedin", "content_marketing", "referral_program")
targeted_ads = {
    "content_marketing": {"S2": 29000},
    "referral_program": {"S3": 10000},
}
for group_id in new_individuals:
    for channel in channels:
        targeted_ads.setdefault(channel, {})[group_id] = 500

if new_individuals:
    show("new_group_ads", nm.marketing.set_targeted_ad_spend(targeted_ads))

reply = (
    "You are right that caps should match real work, not feel arbitrary. We are reviewing "
    "heavy-use accounts for clear, predictable headroom. Send your workspace ID and daily peak, "
    "and we will confirm the best allowance and upgrade path for your workflow."
)
assert len(reply) <= 280, len(reply)
show("social", nm.marketing.post_social_media(reply, reply_to_post_id=611))

show("new_individual_groups", new_individuals)
show("research_attempts", attempts)
"
  }
}

