/bin/bash -c "./novamind-operation python-c \"import novamind_api as nm; d=nm.query('SELECT day,ROUND(SUM(amount),2) AS cash FROM ledger WHERE day<=364 GROUP BY day ORDER BY day')['rows']; cum=[]; t=0.0
for r in d:
 t+=r['cash']; cum.append((r['day'],t))
p=nm.query('SELECT submit_day,horizon_days,predicted_value,predicted_lower,predicted_upper FROM predictions ORDER BY submit_day,horizon_days')['rows']
cash={x:y for x,y in cum}
for r in p:
 target=r['submit_day']+r['horizon_days']; a=cash.get(target)
 if a is not None:
  print(r['submit_day'],r['horizon_days'],'pred',round(r['predicted_value']), 'lo',round(r['predicted_lower']),'hi',round(r['predicted_upper']),'actual',round(a),'err%',round(100*(r['predicted_value']-a)/a,1) if a else None,'cover',r['predicted_lower']<=a<=r['predicted_upper'])\""

